using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class BuildDetailedKnight {
 [Serializable] public class Geometry {public float[] vertices,uv,normals;}
 struct Joint {public HumanBodyBones id;public Vector3 start,end;public Joint(HumanBodyBones b,Vector3 s,Vector3 e){id=b;start=s;end=e;}}
 const string folder="Assets/03_Models/Characters/CindersDetailed/Knight";
 static float Distance(Vector3 p,Joint j){var d=j.end-j.start;return Vector3.Distance(p,j.start+d*Mathf.Clamp01(Vector3.Dot(p-j.start,d)/d.sqrMagnitude));}
 public static string Run(){AssetDatabase.Refresh();var src=JsonUtility.FromJson<Geometry>(System.IO.File.ReadAllText(folder+"/KnightGeometry.json"));var list=new List<Joint>{new Joint(HumanBodyBones.Hips,new Vector3(0,.94f,0),new Vector3(0,1.08f,0)),new Joint(HumanBodyBones.Spine,new Vector3(0,1.08f,0),new Vector3(0,1.23f,0)),new Joint(HumanBodyBones.Chest,new Vector3(0,1.23f,0),new Vector3(0,1.49f,0)),new Joint(HumanBodyBones.Head,new Vector3(0,1.61f,0),new Vector3(0,1.8f,0))};
 foreach(bool l in new[]{true,false}){float x=l?-1:1;list.Add(new Joint(l?HumanBodyBones.LeftUpperArm:HumanBodyBones.RightUpperArm,new Vector3(x*.25f,1.44f,0),new Vector3(x*.46f,1.24f,0)));list.Add(new Joint(l?HumanBodyBones.LeftLowerArm:HumanBodyBones.RightLowerArm,new Vector3(x*.46f,1.24f,0),new Vector3(x*.64f,1.12f,.015f)));list.Add(new Joint(l?HumanBodyBones.LeftHand:HumanBodyBones.RightHand,new Vector3(x*.64f,1.12f,.015f),new Vector3(x*.69f,1.07f,.015f)));list.Add(new Joint(l?HumanBodyBones.LeftUpperLeg:HumanBodyBones.RightUpperLeg,new Vector3(x*.13f,.94f,0),new Vector3(x*.14f,.53f,0)));list.Add(new Joint(l?HumanBodyBones.LeftLowerLeg:HumanBodyBones.RightLowerLeg,new Vector3(x*.14f,.53f,0),new Vector3(x*.14f,.12f,0)));list.Add(new Joint(l?HumanBodyBones.LeftFoot:HumanBodyBones.RightFoot,new Vector3(x*.14f,.12f,0),new Vector3(x*.14f,.06f,.15f)));}
 foreach(string role in new[]{"Warrior","Tank"}){var go=UnityEngine.Object.Instantiate(Resources.Load<GameObject>("Presentation/Human/HumanPlayer"));go.name=role+" - Armadura del exiliado";var a=go.GetComponentInChildren<Animator>();a.enabled=false;foreach(var r in go.GetComponentsInChildren<Renderer>())UnityEngine.Object.DestroyImmediate(r.gameObject);var bones=list.Select(j=>a.GetBoneTransform(j.id)).ToArray();var rotations=new Quaternion[list.Count];
 for(int j=0;j<list.Count;j++){var id=list[j].id;Vector3 direction=Vector3.up;if(id.ToString().Contains("UpperArm"))direction=a.GetBoneTransform(id==HumanBodyBones.LeftUpperArm?HumanBodyBones.LeftLowerArm:HumanBodyBones.RightLowerArm).position-bones[j].position;else if(id.ToString().Contains("LowerArm"))direction=a.GetBoneTransform(id==HumanBodyBones.LeftLowerArm?HumanBodyBones.LeftHand:HumanBodyBones.RightHand).position-bones[j].position;else if(id.ToString().Contains("Hand"))direction=(id==HumanBodyBones.LeftHand?Vector3.left:Vector3.right);else if(id.ToString().Contains("UpperLeg"))direction=a.GetBoneTransform(id==HumanBodyBones.LeftUpperLeg?HumanBodyBones.LeftLowerLeg:HumanBodyBones.RightLowerLeg).position-bones[j].position;else if(id.ToString().Contains("LowerLeg"))direction=a.GetBoneTransform(id==HumanBodyBones.LeftLowerLeg?HumanBodyBones.LeftFoot:HumanBodyBones.RightFoot).position-bones[j].position;else if(id.ToString().Contains("Foot"))direction=new Vector3(0,-.06f,.15f);rotations[j]=Quaternion.FromToRotation(list[j].end-list[j].start,direction);}
 int n=src.vertices.Length/3;var v=new Vector3[n];var normals=new Vector3[n];var uv=new Vector2[n];var w=new BoneWeight[n];
 for(int i=0;i<n;i++){var p=new Vector3(src.vertices[i*3],src.vertices[i*3+1],src.vertices[i*3+2]);var normal=new Vector3(src.normals[i*3],src.normals[i*3+1],src.normals[i*3+2]);var eligible=Enumerable.Range(0,list.Count).Where(j=>p.y>1.52f&&Mathf.Abs(p.x)<.15f?j==3:p.y<.95f?(j==0||j>=4&&list[j].id.ToString().Contains(p.x<0?"Left":"Right")&&(list[j].id.ToString().Contains("Leg")||list[j].id.ToString().Contains("Foot"))):j!=3);var nearest=eligible.OrderBy(j=>Distance(p,list[j])).Take(2).ToArray();int b0=nearest[0],b1=nearest.Length>1?nearest[1]:b0;float d0=Distance(p,list[b0]),d1=Distance(p,list[b1]);float t=b0==b1?0:Mathf.Clamp01((.07f-(d1-d0))/.14f);w[i]=new BoneWeight{boneIndex0=b0,weight0=1-t,boneIndex1=b1,weight1=t};v[i]=(bones[b0].position+rotations[b0]*(p-list[b0].start))*(1-t)+(bones[b1].position+rotations[b1]*(p-list[b1].start))*t;normals[i]=(rotations[b0]*normal*(1-t)+rotations[b1]*normal*t).normalized;uv[i]=new Vector2(src.uv[i*2],src.uv[i*2+1]);}
 var mesh=new Mesh{name="Armadura texturizada "+role};mesh.vertices=v;mesh.normals=normals;mesh.uv=uv;mesh.triangles=Enumerable.Range(0,n).Select(i=>(i/3)*3+2-i%3).ToArray();mesh.boneWeights=w;mesh.bindposes=bones.Select(b=>b.worldToLocalMatrix*go.transform.localToWorldMatrix).ToArray();mesh.RecalculateBounds();mesh.RecalculateTangents();var path=folder+"/"+role+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){old.Clear();old.vertices=mesh.vertices;old.normals=mesh.normals;old.uv=mesh.uv;old.triangles=mesh.triangles;old.boneWeights=mesh.boneWeights;old.bindposes=mesh.bindposes;old.RecalculateBounds();old.RecalculateTangents();old.UploadMeshData(false);EditorUtility.SetDirty(old);UnityEngine.Object.DestroyImmediate(mesh);mesh=old;}else AssetDatabase.CreateAsset(mesh,path);
 var matPath=folder+"/"+role+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(matPath);if(!mat){mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(mat,matPath);}mat.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(folder+"/armor_default_color.png"));mat.SetColor("_BaseColor",role=="Tank"?new Color(.40f,.46f,.46f):new Color(.68f,.65f,.58f));mat.SetFloat("_Metallic",.65f);mat.SetFloat("_Smoothness",.3f);var imp=(TextureImporter)AssetImporter.GetAtPath(folder+"/armor_default_nmap.png");if(imp.textureType!=TextureImporterType.NormalMap){imp.textureType=TextureImporterType.NormalMap;imp.SaveAndReimport();}mat.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(folder+"/armor_default_nmap.png"));mat.EnableKeyword("_NORMALMAP");mat.SetFloat("_BumpScale",.75f);EditorUtility.SetDirty(mat);
 var body=new GameObject("Armadura texturizada");body.transform.SetParent(go.transform,false);var skin=body.AddComponent<SkinnedMeshRenderer>();skin.sharedMesh=mesh;skin.sharedMaterial=mat;skin.bones=bones;skin.rootBone=a.GetBoneTransform(HumanBodyBones.Hips);skin.localBounds=mesh.bounds;skin.updateWhenOffscreen=true;a.enabled=true;PrefabUtility.SaveAsPrefabAsset(go,"Assets/Resources/Presentation/Classes/"+role+".prefab");UnityEngine.Object.DestroyImmediate(go);}
 AssetDatabase.SaveAssets();return "Knight and Tank skinned to existing humanoid avatar; source weapons removed; textured URP materials";}
}


